class BinnedLogDistribution:
    """Piecewise-constant log-probability lookup with a right tail bin."""

    def __init__(self, spec: Mapping):
        self.min = int(spec.get("min", 0))
        self.max = int(spec["max"])
        self.bin_size = int(spec.get("bin_size", 1))
        if self.bin_size <= 0:
            raise ValueError("bin_size must be positive")
        self.log_probs = np.asarray(spec["log_probs"], dtype=np.float64)
        if self.log_probs.ndim != 1 or self.log_probs.size == 0:
            raise ValueError("log_probs must be a non-empty 1D array")
        self.tail_index = self.log_probs.size - 1

    def logp(self, value: int) -> float:
        v = int(value)
        if v < self.min:
            return NEG_INF
        if v > self.max:
            return float(self.log_probs[self.tail_index])
        idx = (v - self.min) // self.bin_size
        idx = min(max(idx, 0), self.tail_index)
        return float(self.log_probs[idx])


