def _build_gene_path(seq_len: int, gs: int, ge: int) -> np.ndarray:
    """Canonical START/CDS/STOP path for one ORF on [gs, ge)."""
    h = ProkaryoticStrandHMM
    path = np.full(seq_len, h.IGR, dtype=np.int32)
    if ge - gs < 6 or gs < 0 or ge > seq_len:
        return path
    for k in range(3):
        path[gs + k] = h.START0 + k
    for pos in range(gs + 3, ge - 3):
        path[pos] = h.CDS0 + ((pos - (gs + 3)) % 3)
    for k in range(3):
        path[ge - 3 + k] = h.STOP0 + k
    return path


def segmental_overlap_range(max_depth: int) -> Tuple[int, ...]:
    """Same-strand negative gaps from -1 through -max_depth inclusive."""
    if max_depth < 1:
        return ()
    return tuple(range(-1, -max_depth - 1, -1))


def _segment_emit_trans_score(
    log_emit: np.ndarray,
    log_trans: np.ndarray,
    path: np.ndarray,
    lo: int,
    hi: int,
    *,
    init: float = 0.0,
) -> float:
    """Score emissions + transitions on path[lo:hi) with optional init at lo."""
    if hi <= lo:
        return init
    span = hi - lo
    path_slice = path[:span] if len(path) == span else path[lo:hi]
    emit = log_emit[np.arange(lo, hi), path_slice]
    emit = emit[emit > -1e20]
    score = init + float(emit.sum())
    if span > 1:
        trans = log_trans[path_slice[:-1], path_slice[1:]]
        trans = trans[trans > -1e20]
        score += float(trans.sum())
    return score


class ViterbiAnchoredScorer:
    """Prefix-summed emissions + explicit HMM transition table for segment DP."""

    def __init__(
        self,
        probs_6: np.ndarray,
        seq: str,
        stats_json: Mapping,
        *,
        alpha: float,
        start_emission_scale: float,
        use_codon_c: bool = True,
        igr_topology: str = "single",
        igr_fit_json: Path | None = None,
        igr_pi_short: float | None = None,
        igr_mean_short: float | None = None,
        igr_mean_long: float | None = None,
        overlap_probs: Dict[str, float] | None = None,
        segmental_overlap_score: str = "legacy",
        empirical_connector_prior_lambda: float | None = None,
        boundary_emit_floor: float | None = None,
        max_overlap_depth: int = 50,
        overlap_emission_scale: float = 1.0,
    ):
        #: Weight on the connector's shared-base emission term. Both ORF nodes
        #: have already consumed the emissions of the overlapped bases; the
        #: connector then adds 0.5*(log b_prev + log b_next) per shared base on
        #: top (~0.22 nats/nt at b=0.8, so ~22 nats against a 100 nt overlap).
        #: 1.0 is the historical behaviour; 0 removes the extra charge.
        self.overlap_emission_scale = float(overlap_emission_scale)
        #: Deepest same-strand overlap the connector will score. Was a bare
        #: literal 50 in four places, so --max-overlap-depth reached
        #: allowed_overlaps and the length prior but NOT the connector, and the
        #: DP could never choose a same-strand overlap deeper than 50 nt however
        #: the flag was set. Measured cost before the fix: 28 real overlapping
        #: pairs on E. coli K-12 and 38 on M. tuberculosis were unrepresentable
        #: (reference reaches 2,400 and 1,058 nt). See
        #: results/caller_comparison/FINDINGS.md section 7.
        self.max_overlap_depth = int(max_overlap_depth)
        #: Clamp on the START/STOP emission triples. Without it a locus whose
        #: START channel is silent contributes ~-1000 nats (start_emission_scale
        #: multiplies the log-emission), which vetoes the gene no matter how good
        #: the coding body is. Flooring lets START/STOP still RANK candidate
        #: boundaries while removing their power to decide gene existence --
        #: measured on K-12: START supplies 91% of the gene-vs-IGR deficit at
        #: missed genes, and is usable at only 10% of them vs 98% of called genes.
        self.boundary_emit_floor = boundary_emit_floor
        self.seq = seq.upper()
        self.alpha = float(alpha)
        self.start_emission_scale = float(start_emission_scale)
        self.segmental_overlap_score = str(segmental_overlap_score)
        if self.segmental_overlap_score not in {"legacy", "multihot", "empirical_multihot"}:
            raise ValueError(
                "segmental_overlap_score must be 'legacy', 'multihot', or "
                "'empirical_multihot', "
                f"got {segmental_overlap_score!r}"
            )
        self.empirical_connector_prior_lambda = empirical_connector_prior_lambda
        probs_arr = np.asarray(probs_6, dtype=np.float32)
        b_ch = probs_arr * (1.0 - self.alpha) + (1.0 - probs_arr) * (self.alpha / (6 - 1))
        b_min = self.alpha / (6 - 1)
        self.log_channel_b = np.log(np.clip(b_ch, b_min, None)).astype(np.float64)
        self.hmm = build_strand_hmm(
            dict(stats_json),
            alpha=alpha,
            trainable=False,
            start_emission_scale=start_emission_scale,
            igr_topology=igr_topology,
            igr_fit_json=igr_fit_json,
            igr_pi_short=igr_pi_short,
            igr_mean_short=igr_mean_short,
            igr_mean_long=igr_mean_long,
            overlap_probs=overlap_probs,
        )
        if not use_codon_c:
            self._zero_codon_constraints()
        triplet_plus, _ = encode_triplets(self.seq)
        log_emit = self.hmm.log_emission(
            torch.from_numpy(np.asarray(probs_6, dtype=np.float32)),
            torch.from_numpy(triplet_plus).long(),
        ).detach().cpu().numpy().astype(np.float64)
        self.log_emit = log_emit
        self.log_trans = self.hmm.log_transitions().detach().cpu().numpy().astype(np.float64)
        self.log_init = self.hmm.log_init().detach().cpu().numpy().astype(np.float64)
        self.prefix = np.vstack([
            np.zeros((1, log_emit.shape[1]), dtype=np.float64),
            np.cumsum(log_emit, axis=0),
        ])
        pos = np.arange(log_emit.shape[0])
        self.cds_phase_prefix = np.zeros((3, log_emit.shape[0] + 1), dtype=np.float64)
        for phase0 in range(3):
            states = self.hmm.CDS0 + ((pos - phase0) % 3)
            vals = log_emit[pos, states]
            vals = np.where(vals < -1e20, 0.0, vals)
            self.cds_phase_prefix[phase0, 1:] = np.cumsum(vals)

    def _zero_codon_constraints(self) -> None:
        def _zero_table(_self=self.hmm):
            return torch.zeros(_self.NUM_STATES, 65, dtype=torch.float32)

        self.hmm.log_c_table = _zero_table  # type: ignore

    def state_sum(self, start: int, end: int, state: int) -> float:
        if end <= start:
            return 0.0
        return float(self.prefix[end, state] - self.prefix[start, state])

    def igr_emission_sum(self, start: int, end: int) -> float:
        igr_states = getattr(self.hmm, "IGR_STATES", (self.hmm.IGR,))
        if len(igr_states) == 1:
            return self.state_sum(start, end, int(igr_states[0]))
        vals = [
            self.state_sum(start, end, int(state)) + math.log(1.0 / len(igr_states))
            for state in igr_states
        ]
        return _logsumexp(vals)

    # Backward-compatible alias used in unit tests.
    def igr_sum(self, start: int, end: int) -> float:
        return self.igr_emission_sum(start, end)

    def cds_orf_score(self, start: int, end: int) -> float:
        """Emission-only ORF score (legacy); prefer ``gene_internal_score``."""
        h = self.hmm
        if end - start < 6:
            return NEG_INF
        start_emit = float(self.log_emit[start, h.START0]
                           + self.log_emit[start + 1, h.START1]
                           + self.log_emit[start + 2, h.START2])
        stop_emit = float(self.log_emit[end - 3, h.STOP0]
                          + self.log_emit[end - 2, h.STOP1]
                          + self.log_emit[end - 1, h.STOP2])
        if self.boundary_emit_floor is not None:
            floor = float(self.boundary_emit_floor)
            start_emit = max(start_emit, floor)
            stop_emit = max(stop_emit, floor)
        cds_start = start + 3
        cds_end = end - 3
        phase0 = cds_start % 3
        body = float(self.cds_phase_prefix[phase0, cds_end]
                     - self.cds_phase_prefix[phase0, cds_start])
        return float(start_emit + body + stop_emit)

    def gene_internal_score(self, start: int, end: int) -> float:
        """Viterbi emission + internal transitions for [start, end), no connectors."""
        h = self.hmm
        length = end - start
        if length < 9 or length % 3 != 0:
            return NEG_INF
        coding_len = length - 6
        cds_codons = coding_len // 3
        score = self.cds_orf_score(start, end)
        score += float(self.log_trans[h.START0, h.START1])
        score += float(self.log_trans[h.START1, h.START2])
        score += float(self.log_trans[h.START2, h.CDS0])
        score += float(cds_codons * self.log_trans[h.CDS0, h.CDS1])
        score += float(cds_codons * self.log_trans[h.CDS1, h.CDS2])
        if cds_codons > 1:
            score += float((cds_codons - 1) * self.log_trans[h.CDS2, h.CDS0])
        score += float(self.log_trans[h.CDS2, h.STOP0])
        score += float(self.log_trans[h.STOP0, h.STOP1])
        score += float(self.log_trans[h.STOP1, h.STOP2])
        return float(score)

    def _gene_geometric_duration(self, start: int, end: int) -> float:
        h = self.hmm
        length = end - start
        if length < 9 or length % 3 != 0:
            return NEG_INF
        cds_codons = (length - 6) // 3
        total = float(self.log_trans[h.CDS2, h.STOP0])
        if cds_codons > 1:
            total += float((cds_codons - 1) * self.log_trans[h.CDS2, h.CDS0])
        return total

    def _igr_geometric_duration(self, gap: int) -> float:
        if gap <= 0:
            return 0.0
        h = self.hmm
        return float(
            (gap - 1) * self.log_trans[h.IGR, h.IGR]
            + self.log_trans[h.IGR, h.START0]
        )

    def _igr_span_viterbi(self, lo: int, hi: int, *, include_exit_to_start: bool) -> float:
        gap = hi - lo
        if gap <= 0:
            return 0.0
        score = self.igr_emission_sum(lo, hi)
        h = self.hmm
        if gap > 1:
            score += float((gap - 1) * self.log_trans[h.IGR, h.IGR])
        if include_exit_to_start:
            score += float(self.log_trans[h.IGR, h.START0])
        return score

    def leader_score(
        self,
        first_start: int,
        length_model: LengthModel | None = None,
        *,
        duration_lambda: float = 0.0,
    ) -> float:
        if first_start < 0:
            return NEG_INF
        if first_start == 0:
            return float(self.log_init[self.hmm.START0])
        emit = float(self.log_init[self.hmm.IGR]) + self.igr_emission_sum(0, first_start)
        geo = self._igr_geometric_duration(first_start)
        if duration_lambda <= 0.0 or length_model is None:
            return emit + geo
        return emit + duration_lambda * length_model.igr_length.logp(first_start)

    def tail_score(
        self,
        last_end: int,
        length_model: LengthModel | None = None,
        *,
        duration_lambda: float = 0.0,
    ) -> float:
        seq_len = len(self.seq)
        if last_end >= seq_len:
            return 0.0
        h = self.hmm
        gap = seq_len - last_end
        emit = float(self.log_trans[h.STOP2, h.IGR]) + self.igr_emission_sum(last_end, seq_len)
        geo = self._igr_geometric_duration(gap) - float(self.log_trans[h.IGR, h.START0])
        if duration_lambda <= 0.0 or length_model is None:
            return emit + geo
        return emit + duration_lambda * length_model.igr_length.logp(gap)

    def all_igr_score(self) -> float:
        seq_len = len(self.seq)
        if seq_len <= 0:
            return 0.0
        h = self.hmm
        score = float(self.log_init[h.IGR]) + self.igr_emission_sum(0, seq_len)
        if seq_len > 1:
            score += float((seq_len - 1) * self.log_trans[h.IGR, h.IGR])
        return score

    def connector_score_plain(self, prev_end: int, next_start: int) -> float:
        gap = next_start - prev_end
        if gap < 0:
            return self._overlap_connector_plain(prev_end, next_start, gap)
        h = self.hmm
        if gap == 0:
            return float(self.log_trans[h.STOP2, h.START0])
        score = float(self.log_trans[h.STOP2, h.IGR])
        score += self._igr_span_viterbi(prev_end, next_start, include_exit_to_start=True)
        return score

    def _overlap_connector_plain(self, prev_end: int, next_start: int, gap: int) -> float:
        if self.segmental_overlap_score == "multihot":
            return self._overlap_connector_multihot(prev_end, next_start, gap)
        return self._overlap_connector_legacy(prev_end, next_start, gap)

    def _overlap_connector_legacy(self, prev_end: int, next_start: int, gap: int) -> float:
        h = self.hmm
        if gap == -1:
            return float(self.log_trans[h.STOP2, h.START0])
        if gap == -4:
            # Canonical seam: ... Z0, Z1, O4, S2 ... on [next_start, prev_end)
            lo, hi = next_start, prev_end
            if hi - lo < 4:
                return NEG_INF
            path = np.full(hi - lo, h.IGR, dtype=np.int32)
            path[hi - lo - 3] = h.STOP0
            path[hi - lo - 2] = h.STOP1
            path[hi - lo - 1] = h.START_OVERLAP_4
            return _segment_emit_trans_score(
                self.log_emit, self.log_trans, path, lo, hi,
            )
        if gap == -7:
            lo, hi = next_start, prev_end
            if hi - lo < 7:
                return NEG_INF
            path = np.full(hi - lo, h.IGR, dtype=np.int32)
            path[hi - lo - 3] = h.STOP0
            path[hi - lo - 2] = h.START_OVERLAP_7
            path[hi - lo - 1] = h.START1
            return _segment_emit_trans_score(
                self.log_emit, self.log_trans, path, lo, hi,
            )
        d = prev_end - next_start
        if d < 2 or d > self.max_overlap_depth:
            return NEG_INF
        lo, hi = next_start, prev_end
        path = np.full(d, h.IGR, dtype=np.int32)
        if d >= 3:
            path[d - 3] = h.STOP0
            path[d - 2] = h.STOP1
            path[d - 1] = h.STOP2
        init = float(self.log_trans[h.STOP2, int(path[0])])
        return _segment_emit_trans_score(
            self.log_emit, self.log_trans, path, lo, hi, init=init,
        )

    def _overlap_transition_skeleton_score(
        self,
        prev_end: int,
        next_start: int,
        gap: int,
    ) -> float:
        """Transition-only counterpart of the legacy overlap connector.

        Multihot overlap scoring keeps the old branch/topology score but replaces
        the synthetic single-label overlap-window emissions with a direct
        multi-label score from the NN channels.
        """
        h = self.hmm
        if gap == -1:
            return float(self.log_trans[h.STOP2, h.START0])
        d = prev_end - next_start
        if d < 2 or d > self.max_overlap_depth:
            return NEG_INF
        if gap == -4:
            path = np.full(d, h.IGR, dtype=np.int32)
            path[d - 3] = h.STOP0
            path[d - 2] = h.STOP1
            path[d - 1] = h.START_OVERLAP_4
            init = 0.0
        elif gap == -7:
            path = np.full(d, h.IGR, dtype=np.int32)
            path[d - 3] = h.STOP0
            path[d - 2] = h.START_OVERLAP_7
            path[d - 1] = h.START1
            init = 0.0
        else:
            path = np.full(d, h.IGR, dtype=np.int32)
            if d >= 3:
                path[d - 3] = h.STOP0
                path[d - 2] = h.STOP1
                path[d - 1] = h.STOP2
            init = float(self.log_trans[h.STOP2, int(path[0])])
        score = init
        if d > 1:
            trans = self.log_trans[path[:-1], path[1:]]
            trans = trans[trans > -1e20]
            score += float(trans.sum())
        return float(score)

    def _prev_overlap_role_log_b(self, pos: int, prev_end: int) -> float:
        """NN log-b evidence for the previous gene's role at an overlap base."""
        # Previous gene occupies [prev_start, prev_end); its last three bases are
        # STOP0/1/2, and bases before that are CDS with phase implied by prev_end.
        if pos >= prev_end - 3:
            return float(self.log_channel_b[pos, 5])  # STOP channel
        frame = (pos - (prev_end - 6)) % 3
        return float(self.log_channel_b[pos, 1 + frame])  # CDS frame channel

    def _next_overlap_role_log_b(self, pos: int, next_start: int) -> float:
        """NN log-b evidence for the next gene's role at an overlap base."""
        # Next gene occupies [next_start, next_end); its first three bases are
        # START0/1/2, and bases after that are CDS.
        if pos < next_start + 3:
            # The next ORF node already applies start_emission_scale to START
            # states.  Keep the multihot connector as an unscaled compatibility
            # edge so overlap windows are not dominated by a second full-strength
            # START penalty/reward.
            return float(self.log_channel_b[pos, 4])  # START channel
        frame = (pos - (next_start + 3)) % 3
        return float(self.log_channel_b[pos, 1 + frame])  # CDS frame channel

    def _overlap_multihot_emission_score(self, prev_end: int, next_start: int) -> float:
        """Score overlap-window emissions using both genes' multihot roles.

        The connector is an edge compatibility term on top of two already-scored
        ORF nodes.  To keep its magnitude comparable to the legacy one-state
        connector, use the mean of previous-role and next-role log evidence at
        each base rather than summing both labels at full strength.
        """
        if self.overlap_emission_scale == 0.0:
            return 0.0
        score = 0.0
        for pos in range(next_start, prev_end):
            prev_log_b = self._prev_overlap_role_log_b(pos, prev_end)
            next_log_b = self._next_overlap_role_log_b(pos, next_start)
            score += 0.5 * (prev_log_b + next_log_b)
        return float(score * self.overlap_emission_scale)

    def _overlap_connector_multihot(self, prev_end: int, next_start: int, gap: int) -> float:
        d = prev_end - next_start
        if d < 1 or d > self.max_overlap_depth:
            return NEG_INF
        return (
            self._overlap_transition_skeleton_score(prev_end, next_start, gap)
            + self._overlap_multihot_emission_score(prev_end, next_start)
        )

    def gene_score(
        self,
        start: int,
        end: int,
        length_model: LengthModel | None,
        *,
        duration_lambda: float,
    ) -> float:
        base = self.gene_internal_score(start, end)
        if duration_lambda <= 0.0 or length_model is None:
            return base
        geo = self._gene_geometric_duration(start, end)
        emp = length_model.gene_length.logp(end - start)
        return base - geo + duration_lambda * emp

    def connector_score(
        self,
        prev_end: int,
        next_start: int,
        length_model: LengthModel | None,
        *,
        duration_lambda: float,
    ) -> float:
        gap = next_start - prev_end
        if self.segmental_overlap_score == "empirical_multihot":
            return self._empirical_multihot_connector_score(
                prev_end,
                next_start,
                gap,
                length_model,
                duration_lambda=duration_lambda,
            )
        h = self.hmm
        if gap < 0:
            base = self._overlap_connector_plain(prev_end, next_start, gap)
            if duration_lambda <= 0.0 or length_model is None:
                return base
            return base + duration_lambda * length_model.overlap_logp(gap)
        if gap == 0:
            base = float(self.log_trans[h.STOP2, h.START0])
            if duration_lambda <= 0.0 or length_model is None:
                return base
            return base + duration_lambda * length_model.igr_length.logp(0)
        emit = float(self.log_trans[h.STOP2, h.IGR]) + self.igr_emission_sum(prev_end, next_start)
        geo = self._igr_geometric_duration(gap)
        if duration_lambda <= 0.0 or length_model is None:
            return emit + geo
        return emit + duration_lambda * length_model.igr_length.logp(gap)

    def _empirical_multihot_connector_score(
        self,
        prev_end: int,
        next_start: int,
        gap: int,
        length_model: LengthModel | None,
        *,
        duration_lambda: float,
    ) -> float:
        """Biological adjacency score with no legacy transition skeleton.

        This connector treats the edge between two selected ORFs as a direct
        adjacency model:

        * gap < 0: shared bases are scored from both ORF roles using the
          multihot overlap emission; an empirical overlap-depth prior may be
          added through ``LengthModel.overlap_logp``.
        * gap == 0: no bases lie between the ORFs; only the empirical zero-IGR
          prior is available.
        * gap > 0: intervening bases are scored as IGR, plus the empirical IGR
          length prior.

        Unlike ``legacy`` and ``multihot``, no STOP/IGR/START transition path is
        added for the connector.
        """
        if gap < 0:
            d = -gap
            if d < 1 or d > self.max_overlap_depth:
                return NEG_INF
            score = self._overlap_multihot_emission_score(prev_end, next_start)
            prior_lambda = (
                duration_lambda
                if self.empirical_connector_prior_lambda is None
                else float(self.empirical_connector_prior_lambda)
            )
            if prior_lambda > 0.0 and length_model is not None:
                score += prior_lambda * length_model.overlap_logp(gap)
            return float(score)
        if gap == 0:
            prior_lambda = (
                duration_lambda
                if self.empirical_connector_prior_lambda is None
                else float(self.empirical_connector_prior_lambda)
            )
            if prior_lambda > 0.0 and length_model is not None:
                return float(prior_lambda * length_model.igr_length.logp(0))
            return 0.0
        score = self.igr_emission_sum(prev_end, next_start)
        prior_lambda = (
            duration_lambda
            if self.empirical_connector_prior_lambda is None
            else float(self.empirical_connector_prior_lambda)
        )
        if prior_lambda > 0.0 and length_model is not None:
            score += prior_lambda * length_model.igr_length.logp(gap)
        return float(score)


# Backward-compatible name used in tests / older call sites.
SegmentalEmissionScorer = ViterbiAnchoredScorer


def enumerate_orfs(
    seq: str,
    scorer: ViterbiAnchoredScorer | None = None,
    length_model: LengthModel | None = None,
    *,
    min_nt: int = 90,
    max_gene_len: int = 20000,
    start_bonus: Mapping[str, float] | None = None,
    duration_lambda: float = 0.0,
    gene_length_lambda: float = 0.0,
    gene_length_center: bool = False,
    gene_entry_bonus: float = 0.0,
    rbs_bonus: np.ndarray | None = None,
    start_rank_q: np.ndarray | None = None,
    start_rank_lambda: float = 0.0,
    start_rank_center: bool = True,
    start_rank_existence_lambda: float | None = None,
) -> List[OrfCandidate]:
    seq_u = seq.upper()
    n = len(seq_u)
    starts_by_frame: List[List[int]] = [[], [], []]
    last_stop_by_frame = [-1, -1, -1]
    out: List[OrfCandidate] = []
    bonus = start_bonus or {}
    use_rank = start_rank_q is not None and start_rank_lambda != 0.0
    for pos in range(0, n - 2):
        codon = seq_u[pos:pos + 3]
        frame = pos % 3
        if codon in VALID_START_SET:
            starts_by_frame[frame].append(pos)
        if codon not in VALID_STOP_SET:
            continue
        end = pos + 3
        frame_starts = starts_by_frame[frame]
        # Candidates sharing this stop form one competing set. The neural start
        # ranker is normalised over exactly that set, so buffer the group.
        group: List[Tuple[int, str, float]] = []
        for start in reversed(frame_starts):
            length = end - start
            if length > max_gene_len:
                break
            if start <= last_stop_by_frame[frame]:
                break
            if length < min_nt:
                continue
            score = 0.0
            if scorer is not None:
                score += scorer.gene_score(
                    start, end, length_model, duration_lambda=duration_lambda,
                )
            if gene_length_lambda > 0.0 and length_model is not None:
                lp = length_model.gene_length.logp(length)
                if gene_length_center:
                    # Subtract the prior's value at its anchor (the shortest allowed
                    # length). Raw logp is ~-6.8 at 30 nt and ~-7.8 at 900 nt, so its
                    # constant offset dominates its 0.97-nat slope by ~7x; scaling the
                    # raw value by lambda therefore acts as a per-gene existence
                    # penalty and culls short ORFs, the opposite of the intent.
                    # Centering makes the term 0 at the anchor and negative above it,
                    # isolating the length preference.
                    lp -= length_model.gene_length.logp(length_model.gene_length.min)
                score += gene_length_lambda * lp
            score += float(bonus.get(seq_u[start:start + 3], 0.0))
            # Length-independent reward for emitting a gene at all. A short ORF
            # competes against IGR, not against a long gene, so its margin is
            # small in absolute nats; a constant bonus lowers the gene-entry
            # threshold and therefore helps short ORFs disproportionately.
            score += gene_entry_bonus
            if rbs_bonus is not None:
                # Self-trained, genome-specific RBS log-odds for a start here.
                # Independent of the CNN: on K-12 it prefers the correct start
                # 2:1 at the loci the START channel gets wrong.
                score += float(rbs_bonus[start])
            group.append((start, seq_u[start:start + 3], score))
        if group and use_rank:
            # Genome-specific neural ranker over this stop's candidate starts.
            # Centred by log-sum-exp *within the group*, so the term is a
            # relative preference among competitors summing to ~0 influence on
            # whether the locus is a gene at all -- the CNN+BiLSTM body keeps
            # that decision. Without centring an ORF whose every candidate
            # scores poorly would be pushed below IGR on start evidence alone.
            # q_i = (q_i - logsumexp_j q_j) + logsumexp_j q_j
            #        \____ boundary ____/      \__ existence __/
            # The first varies within the candidate set and only reorders starts;
            # the second is constant across it, so it acts purely on whether the
            # locus beats IGR. On the 9-genome test set the two do different jobs
            # (boundary fixes 492 vs 463; un-called loci recovered 74 vs 234), so
            # they take independent weights instead of the lambda_b == lambda_e
            # diagonal. lambda_e = 0 reproduces the centred arm exactly;
            # lambda_e = lambda_b reproduces the uncentred arm exactly.
            lam_e = (start_rank_existence_lambda
                     if start_rank_existence_lambda is not None
                     else (0.0 if start_rank_center else start_rank_lambda))
            q = np.array([float(start_rank_q[s]) for s, _, _ in group],
                         dtype=np.float64)
            lse = float(_logsumexp(q))
            group = [(s, c, sc + start_rank_lambda * (qi - lse) + lam_e * lse)
                     for (s, c, sc), qi in zip(group, q)]
        for start, start_cod, score in group:
            out.append(OrfCandidate(start, end, start_cod, codon, score))
        last_stop_by_frame[frame] = pos
    out.sort(key=lambda g: (g.end, g.start))
    return out


def segmental_decode_strand(
    probs_6: np.ndarray,
    seq: str,
    seq_name: str,
    stats_json: Mapping,
    length_model: LengthModel | None,
    *,
    alpha: float,
    start_emission_scale: float,
    use_codon_c: bool = True,
    min_nt: int = 90,
    max_gene_len: int | None = None,
    allowed_overlaps: Sequence[int] = (-1, -4, -7),
    start_type_bonus: Mapping[str, float] | None = None,
    igr_topology: str = "single",
    igr_fit_json: Path | None = None,
    igr_pi_short: float | None = None,
    igr_mean_short: float | None = None,
    igr_mean_long: float | None = None,
    overlap_probs: Dict[str, float] | None = None,
    duration_lambda: float = 0.0,
    gene_length_lambda: float = 0.0,
    gene_length_center: bool = False,
    gene_entry_bonus: float = 0.0,
    rbs_bonus: np.ndarray | None = None,
    start_rank_q: np.ndarray | None = None,
    start_rank_lambda: float = 0.0,
    start_rank_center: bool = True,
    start_rank_existence_lambda: float | None = None,
    segmental_overlap_score: str = "legacy",
    empirical_connector_prior_lambda: float | None = None,
    boundary_emit_floor: float | None = None,
    overlap_emission_scale: float = 1.0,
) -> List[Dict]:
    scorer = ViterbiAnchoredScorer(
        probs_6,
        seq,
        stats_json,
        alpha=alpha,
        start_emission_scale=start_emission_scale,
        use_codon_c=use_codon_c,
        igr_topology=igr_topology,
        igr_fit_json=igr_fit_json,
        igr_pi_short=igr_pi_short,
        igr_mean_short=igr_mean_short,
        igr_mean_long=igr_mean_long,
        overlap_probs=overlap_probs,
        segmental_overlap_score=segmental_overlap_score,
        empirical_connector_prior_lambda=empirical_connector_prior_lambda,
        boundary_emit_floor=boundary_emit_floor,
        max_overlap_depth=max(abs(min(allowed_overlaps, default=-50)), 1),
        overlap_emission_scale=overlap_emission_scale,
    )
    max_len = int(max_gene_len or (length_model.max_gene_len if length_model else 20000))
    candidates = enumerate_orfs(
        seq,
        scorer,
        length_model,
        min_nt=min_nt,
        max_gene_len=max_len,
        start_bonus=start_type_bonus,
        duration_lambda=duration_lambda,
        gene_length_lambda=gene_length_lambda,
        gene_length_center=gene_length_center,
        gene_entry_bonus=gene_entry_bonus,
        rbs_bonus=rbs_bonus,
        start_rank_q=start_rank_q,
        start_rank_lambda=start_rank_lambda,
        start_rank_center=start_rank_center,
        start_rank_existence_lambda=start_rank_existence_lambda,
    )
    picked = _longest_path(
        candidates,
        scorer,
        length_model,
        set(int(x) for x in allowed_overlaps),
        duration_lambda=duration_lambda,
    )
    return [
        {
            "seqid": seq_name,
            "strand": "+",
            "start": g.start,
            "end": g.end,
            "start_codon": g.start_codon,
            "stop_codon": g.stop_codon,
            "length": g.length,
            "score": g.score,
        }
        for g in picked
    ]


def _segmental_decode_worker(payload: Mapping[str, Any]) -> Tuple[str, List[Dict]]:
    strand = str(payload["strand"])
    genes = segmental_decode_strand(
        payload["probs_6"],
        payload["seq"],
        payload["seq_name"],
        payload["stats_json"],
        payload["length_model"],
        alpha=float(payload["alpha"]),
        start_emission_scale=float(payload["start_emission_scale"]),
        use_codon_c=bool(payload["use_codon_c"]),
        min_nt=int(payload["min_nt"]),
        max_gene_len=payload["max_gene_len"],
        allowed_overlaps=payload["allowed_overlaps"],
        start_type_bonus=payload["start_type_bonus"],
        igr_topology=payload["igr_topology"],
        igr_fit_json=payload["igr_fit_json"],
        igr_pi_short=payload["igr_pi_short"],
        igr_mean_short=payload["igr_mean_short"],
        igr_mean_long=payload["igr_mean_long"],
        overlap_probs=payload["overlap_probs"],
        duration_lambda=float(payload["duration_lambda"]),
        gene_length_lambda=float(payload["gene_length_lambda"]),
        gene_length_center=bool(payload.get("gene_length_center", False)),
        gene_entry_bonus=float(payload.get("gene_entry_bonus", 0.0)),
        rbs_bonus=payload.get("rbs_bonus"),
        start_rank_q=payload.get("start_rank_q"),
        start_rank_lambda=payload.get("start_rank_lambda", 0.0),
        start_rank_center=payload.get("start_rank_center", True),
        start_rank_existence_lambda=payload.get("start_rank_existence_lambda"),
        segmental_overlap_score=str(payload["segmental_overlap_score"]),
        empirical_connector_prior_lambda=payload["empirical_connector_prior_lambda"],
        overlap_emission_scale=float(payload.get("overlap_emission_scale", 1.0)),
        boundary_emit_floor=payload.get("boundary_emit_floor"),
    )
    return strand, genes


def annotate_strategy_a_segmental(
    probs_11: np.ndarray,
    seq: str,
    seq_name: str,
    stats_json: Mapping,
    length_model: LengthModel | None,
    *,
    alpha: float,
    use_codon_c: bool,
    same_strand_max_ov: int,
    opposite_max_ov: int,
    start_emission_scale: float = 1.0,
    min_nt: int = 90,
    allowed_overlaps: Sequence[int] = (-1, -4, -7),
    start_type_bonus: Mapping[str, float] | None = None,
    igr_topology: str = "single",
    igr_fit_json: Path | None = None,
    igr_pi_short: float | None = None,
    igr_mean_short: float | None = None,
    igr_mean_long: float | None = None,
    overlap_probs: Dict[str, float] | None = None,
    duration_lambda: float = 1.0,
    gene_length_lambda: float = 0.0,
    gene_length_center: bool = False,
    gene_entry_bonus: float = 0.0,
    rbs_bonus_plus: np.ndarray | None = None,
    rbs_bonus_minus: np.ndarray | None = None,
    start_rank_q_plus: np.ndarray | None = None,
    start_rank_q_minus: np.ndarray | None = None,
    start_rank_lambda: float = 0.0,
    start_rank_center: bool = True,
    start_rank_existence_lambda: float | None = None,
    segmental_overlap_score: str = "legacy",
    empirical_connector_prior_lambda: float | None = None,
    boundary_emit_floor: float | None = None,
    overlap_emission_scale: float = 1.0,
    conflict_resolution: str = "length",
    segmental_workers: int = 1,
) -> List[Dict]:
    from .inference import prodigal_overlap_filter

    rc = reverse_complement_dna(seq)
    common = {
        "seq_name": seq_name,
        "stats_json": stats_json,
        "length_model": length_model,
        "alpha": alpha,
        "start_emission_scale": start_emission_scale,
        "use_codon_c": use_codon_c,
        "min_nt": min_nt,
        "max_gene_len": None,
        "allowed_overlaps": tuple(allowed_overlaps),
        "start_type_bonus": start_type_bonus,
        "igr_topology": igr_topology,
        "igr_fit_json": igr_fit_json,
        "igr_pi_short": igr_pi_short,
        "igr_mean_short": igr_mean_short,
        "igr_mean_long": igr_mean_long,
        "overlap_probs": overlap_probs,
        "duration_lambda": duration_lambda,
        "gene_length_lambda": gene_length_lambda,
        "gene_length_center": gene_length_center,
        "gene_entry_bonus": gene_entry_bonus,
        "segmental_overlap_score": segmental_overlap_score,
        "empirical_connector_prior_lambda": empirical_connector_prior_lambda,
        "boundary_emit_floor": boundary_emit_floor,
        "overlap_emission_scale": overlap_emission_scale,
    }
    tasks = [
        {
            **common,
            "strand": "+",
            "probs_6": slice_plus_channels(probs_11),
            "seq": seq,
            "rbs_bonus": rbs_bonus_plus,
            "start_rank_q": start_rank_q_plus,
            "start_rank_lambda": start_rank_lambda,
            "start_rank_center": start_rank_center,
            "start_rank_existence_lambda": start_rank_existence_lambda,
        },
        {
            **common,
            "strand": "-",
            "probs_6": reverse_for_minus_strand(slice_minus_channels(probs_11)),
            "seq": rc,
            "rbs_bonus": rbs_bonus_minus,
            "start_rank_q": start_rank_q_minus,
            "start_rank_lambda": start_rank_lambda,
            "start_rank_center": start_rank_center,
            "start_rank_existence_lambda": start_rank_existence_lambda,
        },
    ]
    if segmental_workers >= 2:
        with ProcessPoolExecutor(max_workers=min(int(segmental_workers), 2)) as pool:
            results = list(pool.map(_segmental_decode_worker, tasks))
        by_strand = {strand: genes for strand, genes in results}
        plus = by_strand.get("+", [])
        minus_rc = by_strand.get("-", [])
    else:
        plus = _segmental_decode_worker(tasks[0])[1]
        minus_rc = _segmental_decode_worker(tasks[1])[1]
    for g in minus_rc:
        g["strand"] = "-"
    minus = minus_strand_decoded_to_forward(minus_rc, len(seq), seq_name)
    kept_p, kept_m, stats = prodigal_overlap_filter(
        plus,
        minus,
        same_strand_max_ov=same_strand_max_ov,
        opposite_max_ov=opposite_max_ov,
        conflict_resolution=conflict_resolution,
    )
    print(
        f"    prodigal filter: +{stats['n_in_fwd']}/-{stats['n_in_rev']} -> "
        f"+{stats['n_out_fwd']}/-{stats['n_out_rev']}  "
        f"(drop same: {stats['drop_same_strand']}, "
        f"opp-start: {stats['drop_opp_start_overlap']}, "
        f"opp>{opposite_max_ov}: {stats['drop_opp_gt_max']})"
    )
    return kept_p + kept_m


def default_start_type_bonus(stats_json: Mapping) -> Dict[str, float]:
    freqs = stats_json.get("start_codon_freqs") or ECOLI_START_CODON_FREQS
    atg = max(float(freqs.get("ATG", 0.0)), 1e-12)
    return {
        c: math.log(max(float(freqs.get(c, 0.0)), 1e-12) / atg)
        for c in VALID_START_SET
    }


def _longest_path(
    candidates: Sequence[OrfCandidate],
    scorer: ViterbiAnchoredScorer,
    length_model: LengthModel | None,
    allowed_overlaps: set[int],
    *,
    duration_lambda: float,
) -> List[OrfCandidate]:
    if (
        duration_lambda <= 0.0
        and getattr(scorer, "segmental_overlap_score", "legacy") == "empirical_multihot"
        and _can_use_empirical_multihot_fast(scorer, length_model)
    ):
        print(f"    empirical_multihot fast DP: candidates={len(candidates)}")
        return _longest_path_empirical_multihot_fast(candidates, scorer, length_model, allowed_overlaps)
    if duration_lambda <= 0.0 and _can_use_fast_viterbi_anchor(scorer):
        return _longest_path_viterbi_anchor_fast(candidates, scorer, allowed_overlaps)
    return _longest_path_scan(
        candidates,
        scorer,
        length_model,
        allowed_overlaps,
        duration_lambda=duration_lambda,
    )


def _longest_path_scan(
    candidates: Sequence[OrfCandidate],
    scorer: ViterbiAnchoredScorer,
    length_model: LengthModel | None,
    allowed_overlaps: set[int],
    *,
    duration_lambda: float,
) -> List[OrfCandidate]:
    n = len(candidates)
    if n == 0:
        return []
    dp = np.full(n, NEG_INF, dtype=np.float64)
    prev = np.full(n, -1, dtype=np.int64)
    max_igr = len(scorer.seq)
    for j, b in enumerate(candidates):
        best = scorer.leader_score(b.start, length_model, duration_lambda=duration_lambda)
        best_i = -1
        min_prev_end = b.start - max_igr
        max_prev_end = b.start - min([0, *allowed_overlaps])
        for i in range(j - 1, -1, -1):
            a = candidates[i]
            if a.end < min_prev_end:
                break
            if a.end > max_prev_end:
                continue
            gap = b.start - a.end
            if gap >= 0 or gap in allowed_overlaps:
                edge = scorer.connector_score(
                    a.end, b.start, length_model, duration_lambda=duration_lambda,
                )
            else:
                continue
            val = dp[i] + edge
            if val > best:
                best = val
                best_i = i
        dp[j] = best + b.score
        prev[j] = best_i
    best_total = scorer.all_igr_score()
    best_idx = -1
    seq_len = len(scorer.seq)
    for i, g in enumerate(candidates):
        val = dp[i] + scorer.tail_score(g.end, length_model, duration_lambda=duration_lambda)
        if val > best_total:
            best_total = val
            best_idx = i
    path: List[OrfCandidate] = []
    cur = best_idx
    while cur >= 0:
        path.append(candidates[cur])
        cur = int(prev[cur])
    path.reverse()
    return path


def _can_use_fast_viterbi_anchor(scorer: ViterbiAnchoredScorer) -> bool:
    if getattr(scorer, "segmental_overlap_score", "legacy") == "empirical_multihot":
        return False
    igr_states = getattr(scorer.hmm, "IGR_STATES", (scorer.hmm.IGR,))
    return len(igr_states) == 1 and hasattr(scorer.hmm, "IGR")


class _FenwickMax:
    def __init__(self, n: int):
        self.n = int(n)
        self.val = np.full(self.n + 2, NEG_INF, dtype=np.float64)
        self.idx = np.full(self.n + 2, -1, dtype=np.int64)

    def update(self, pos0: int, value: float, cand_idx: int) -> None:
        i = int(pos0) + 1
        while i <= self.n + 1:
            if value > self.val[i]:
                self.val[i] = value
                self.idx[i] = cand_idx
            i += i & -i

    def query(self, pos0: int) -> Tuple[float, int]:
        if pos0 < 0:
            return NEG_INF, -1
        i = min(int(pos0) + 1, self.n + 1)
        best = NEG_INF
        best_idx = -1
        while i > 0:
            if self.val[i] > best:
                best = float(self.val[i])
                best_idx = int(self.idx[i])
            i -= i & -i
        return best, best_idx


class _SegmentTreeMax:
    def __init__(self, n: int):
        self.n = int(n)
        size = 1
        while size < self.n:
            size *= 2
        self.size = size
        self.val = np.full(2 * size, NEG_INF, dtype=np.float64)
        self.idx = np.full(2 * size, -1, dtype=np.int64)

    def update(self, pos0: int, value: float, cand_idx: int) -> None:
        if pos0 < 0:
            return
        pos0 = min(int(pos0), self.n - 1)
        i = pos0 + self.size
        if value <= self.val[i]:
            return
        self.val[i] = value
        self.idx[i] = cand_idx
        i //= 2
        while i:
            left = 2 * i
            right = left + 1
            if self.val[left] >= self.val[right]:
                self.val[i] = self.val[left]
                self.idx[i] = self.idx[left]
            else:
                self.val[i] = self.val[right]
                self.idx[i] = self.idx[right]
            i //= 2

    def query(self, lo0: int, hi0: int) -> Tuple[float, int]:
        if hi0 < lo0 or hi0 < 0 or lo0 >= self.n:
            return NEG_INF, -1
        l = max(0, int(lo0)) + self.size
        r = min(self.n - 1, int(hi0)) + self.size
        best = NEG_INF
        best_idx = -1
        while l <= r:
            if l & 1:
                if self.val[l] > best:
                    best = float(self.val[l])
                    best_idx = int(self.idx[l])
                l += 1
            if not (r & 1):
                if self.val[r] > best:
                    best = float(self.val[r])
                    best_idx = int(self.idx[r])
                r -= 1
            l //= 2
            r //= 2
        return best, best_idx


def _longest_path_viterbi_anchor_fast(
    candidates: Sequence[OrfCandidate],
    scorer: ViterbiAnchoredScorer,
    allowed_overlaps: set[int],
) -> List[OrfCandidate]:
    n = len(candidates)
    if n == 0:
        return []

    h = scorer.hmm
    seq_len = len(scorer.seq)
    igr_state = int(h.IGR)
    igr_prefix = scorer.prefix[:, igr_state]
    loop = float(scorer.log_trans[h.IGR, h.IGR])
    stop_to_igr = float(scorer.log_trans[h.STOP2, h.IGR])
    igr_to_start = float(scorer.log_trans[h.IGR, h.START0])

    dp = np.full(n, NEG_INF, dtype=np.float64)
    prev = np.full(n, -1, dtype=np.int64)
    prefix_best = _FenwickMax(seq_len + 1)
    exact_by_end: Dict[int, Tuple[float, int]] = {}

    j = 0
    while j < n:
        end_value = candidates[j].end
        k = j
        while k < n and candidates[k].end == end_value:
            k += 1

        for idx in range(j, k):
            b = candidates[idx]
            best = scorer.leader_score(b.start, None, duration_lambda=0.0)
            best_i = -1

            pos_val, pos_i = prefix_best.query(b.start - 1)
            if pos_i >= 0:
                const = (
                    igr_prefix[b.start]
                    + (b.start - 1) * loop
                    + stop_to_igr
                    + igr_to_start
                )
                val = pos_val + const
                if val > best:
                    best = float(val)
                    best_i = pos_i

            zero = exact_by_end.get(b.start)
            if zero is not None:
                val = zero[0] + float(scorer.log_trans[h.STOP2, h.START0])
                if val > best:
                    best = float(val)
                    best_i = zero[1]

            for gap in allowed_overlaps:
                if gap >= 0:
                    continue
                target_end = b.start - gap
                exact = exact_by_end.get(target_end)
                if exact is None:
                    continue
                edge = scorer.connector_score(target_end, b.start, None, duration_lambda=0.0)
                val = exact[0] + edge
                if val > best:
                    best = float(val)
                    best_i = exact[1]

            dp[idx] = best + b.score
            prev[idx] = best_i

        for idx in range(j, k):
            g = candidates[idx]
            adjusted = dp[idx] - igr_prefix[g.end] - g.end * loop
            prefix_best.update(g.end, adjusted, idx)
            old = exact_by_end.get(g.end)
            if old is None or dp[idx] > old[0]:
                exact_by_end[g.end] = (float(dp[idx]), idx)
        j = k

    best_total = scorer.all_igr_score()
    best_idx = -1
    for i, g in enumerate(candidates):
        val = dp[i] + scorer.tail_score(g.end, None, duration_lambda=0.0)
        if val > best_total:
            best_total = float(val)
            best_idx = i

    path: List[OrfCandidate] = []
    cur = best_idx
    while cur >= 0:
        path.append(candidates[cur])
        cur = int(prev[cur])
    path.reverse()
    return path


def _can_use_empirical_multihot_fast(
    scorer: ViterbiAnchoredScorer,
    length_model: LengthModel | None,
) -> bool:
    if length_model is None:
        return True
    if getattr(scorer, "segmental_overlap_score", "legacy") != "empirical_multihot":
        return False
    igr_states = getattr(scorer.hmm, "IGR_STATES", (scorer.hmm.IGR,))
    if len(igr_states) != 1 or not hasattr(scorer.hmm, "IGR"):
        return False
    dist = length_model.igr_length
    if dist.min != 0 or dist.bin_size != 1:
        return False
    logs = np.asarray(dist.log_probs, dtype=np.float64)
    finite = logs[: dist.max + 1]
    if finite.size <= 2:
        return False
    slope = finite[1] - finite[0]
    return bool(np.allclose(np.diff(finite), slope, rtol=1e-7, atol=1e-9))


def _empirical_prior_params(
    scorer: ViterbiAnchoredScorer,
    length_model: LengthModel | None,
) -> Tuple[float, float, float, int]:
    prior_lambda = (
        0.0
        if getattr(scorer, "empirical_connector_prior_lambda", None) is None
        else float(scorer.empirical_connector_prior_lambda)
    )
    if prior_lambda <= 0.0 or length_model is None:
        return 0.0, 0.0, 0.0, 0
    dist = length_model.igr_length
    logs = np.asarray(dist.log_probs, dtype=np.float64)
    finite = logs[: dist.max + 1]
    slope = float(finite[1] - finite[0]) if finite.size > 1 else 0.0
    intercept = float(finite[0])
    tail = float(logs[dist.tail_index])
    return prior_lambda, intercept, slope, int(dist.max)


def _longest_path_empirical_multihot_fast(
    candidates: Sequence[OrfCandidate],
    scorer: ViterbiAnchoredScorer,
    length_model: LengthModel | None,
    allowed_overlaps: set[int],
) -> List[OrfCandidate]:
    n = len(candidates)
    if n == 0:
        return []

    h = scorer.hmm
    seq_len = len(scorer.seq)
    igr_state = int(h.IGR)
    igr_prefix = scorer.prefix[:, igr_state]
    prior_lambda, prior_intercept, prior_slope, prior_max = _empirical_prior_params(scorer, length_model)

    dp = np.full(n, NEG_INF, dtype=np.float64)
    prev = np.full(n, -1, dtype=np.int64)
    # For positive IGR gaps with no active/linear prior.
    prefix_plain = _FenwickMax(seq_len + 1)
    # For finite positive gaps with linear log prior and gap in [1, prior_max].
    finite_tree = _SegmentTreeMax(seq_len + 1)
    # For tail positive gaps with constant tail prior and gap > prior_max.
    tail_prefix = _FenwickMax(seq_len + 1)
    exact_by_end: Dict[int, Tuple[float, int]] = {}

    j = 0
    while j < n:
        end_value = candidates[j].end
        k = j
        while k < n and candidates[k].end == end_value:
            k += 1

        for idx in range(j, k):
            b = candidates[idx]
            best = scorer.leader_score(b.start, None, duration_lambda=0.0)
            best_i = -1

            if prior_lambda > 0.0 and prior_max > 0:
                lo = b.start - prior_max
                hi = b.start - 1
                finite_val, finite_i = finite_tree.query(lo, hi)
                if finite_i >= 0:
                    val = (
                        finite_val
                        + float(igr_prefix[b.start])
                        + prior_lambda * (prior_intercept + prior_slope * b.start)
                    )
                    if val > best:
                        best = float(val)
                        best_i = finite_i

                tail_val, tail_i = tail_prefix.query(b.start - prior_max - 1)
                if tail_i >= 0:
                    val = (
                        tail_val
                        + float(igr_prefix[b.start])
                        + prior_lambda * float(length_model.igr_length.log_probs[length_model.igr_length.tail_index])
                    )
                    if val > best:
                        best = float(val)
                        best_i = tail_i
            else:
                pos_val, pos_i = prefix_plain.query(b.start - 1)
                if pos_i >= 0:
                    val = pos_val + float(igr_prefix[b.start])
                    if val > best:
                        best = float(val)
                        best_i = pos_i

            zero = exact_by_end.get(b.start)
            if zero is not None:
                edge = scorer.connector_score(b.start, b.start, length_model, duration_lambda=0.0)
                val = zero[0] + edge
                if val > best:
                    best = float(val)
                    best_i = zero[1]

            for gap in allowed_overlaps:
                if gap >= 0:
                    continue
                target_end = b.start - gap
                exact = exact_by_end.get(target_end)
                if exact is None:
                    continue
                edge = scorer.connector_score(target_end, b.start, length_model, duration_lambda=0.0)
                val = exact[0] + edge
                if val > best:
                    best = float(val)
                    best_i = exact[1]

            dp[idx] = best + b.score
            prev[idx] = best_i

        for idx in range(j, k):
            g = candidates[idx]
            base = dp[idx] - float(igr_prefix[g.end])
            prefix_plain.update(g.end, base, idx)
            if prior_lambda > 0.0 and prior_max > 0:
                finite_tree.update(
                    g.end,
                    base - prior_lambda * prior_slope * g.end,
                    idx,
                )
                tail_prefix.update(g.end, base, idx)
            old = exact_by_end.get(g.end)
            if old is None or dp[idx] > old[0]:
                exact_by_end[g.end] = (float(dp[idx]), idx)
        j = k

    best_total = scorer.all_igr_score()
    best_idx = -1
    for i, g in enumerate(candidates):
        val = dp[i] + scorer.tail_score(g.end, None, duration_lambda=0.0)
        if val > best_total:
            best_total = float(val)
            best_idx = i

    path: List[OrfCandidate] = []
    cur = best_idx
    while cur >= 0:
        path.append(candidates[cur])
        cur = int(prev[cur])
    path.reverse()
    return path


def _has_internal_stop(seq: str, start: int, end: int) -> bool:
    for pos in range(start + 3, end - 3, 3):
        if seq[pos:pos + 3] in VALID_STOP_SET:
            return True
    return False


def _normalize_log_probs(log_probs: np.ndarray) -> np.ndarray:
    m = float(np.max(log_probs))
    z = m + math.log(float(np.sum(np.exp(log_probs - m))))
    return log_probs - z


def _logsumexp(vals: Iterable[float]) -> float:
    arr = np.asarray(list(vals), dtype=np.float64)
    if arr.size == 0:
        return NEG_INF
    m = float(np.max(arr))
    if m <= NEG_INF / 2:
        return NEG_INF
    return m + math.log(float(np.sum(np.exp(arr - m))))
